-- CN task 7 → EN task 1
UPDATE tasks
SET
  title = 'Task 1: if-else Conditional Statement',
  description = 'Learn if-else conditional statements, output pass or fail based on score',
  content_json = '{"a_stage": {"python_code": "score = 85\nif score >= 60:\n    print(\"及格\")\nelse:\n    print(\"不及格\")"}, "c_stage": {"title": "Determine Grade Level (Nested Conditionals)", "blocks_xml": "<xml xmlns=\"https://developers.google.com/blockly/xml\">\n  <block type=\"variables_set\">\n    <field name=\"VAR\">score</field>\n    <value name=\"VALUE\">\n      <block type=\"math_number\">\n        <field name=\"NUM\">85</field>\n      </block>\n    </value>\n    <next>\n      <block type=\"controls_if\">\n        <value name=\"IF0\">\n          <block type=\"logic_compare\">\n            <field name=\"OP\">GTE</field>\n            <value name=\"A\">\n              <block type=\"variables_get\">\n                <field name=\"VAR\">score</field>\n              </block>\n            </value>\n            <value name=\"B\">\n              <block type=\"math_number\">\n                <field name=\"NUM\">90</field>\n              </block>\n            </value>\n          </block>\n        </value>\n        <statement name=\"DO0\">\n          <block type=\"text_print\">\n            <value name=\"TEXT\">\n              <block type=\"text\">\n                <field name=\"TEXT\">Excellent</field>\n              </block>\n            </value>\n          </block>\n        </statement>\n        <statement name=\"ELSE\">\n          <block type=\"controls_if\">\n            <value name=\"IF0\">\n              <block type=\"logic_compare\">\n                <field name=\"OP\">GTE</field>\n                <value name=\"A\">\n                  <block type=\"variables_get\">\n                    <field name=\"VAR\">score</field>\n                  </block>\n                </value>\n                <value name=\"B\">\n                  <block type=\"math_number\">\n                    <field name=\"NUM\">60</field>\n                  </block>\n                </value>\n              </block>\n            </value>\n            <statement name=\"DO0\">\n              <block type=\"text_print\">\n                <value name=\"TEXT\">\n                  <block type=\"text\">\n                    <field name=\"TEXT\">Pass</field>\n                  </block>\n                </value>\n              </block>\n            </statement>\n            <statement name=\"ELSE\">\n              <block type=\"text_print\">\n                <value name=\"TEXT\">\n                  <block type=\"text\">\n                    <field name=\"TEXT\">Fail</field>\n                  </block>\n                </value>\n              </block>\n            </statement>\n          </block>\n        </statement>\n      </block>\n    </next>\n  </block>\n</xml>", "answer_code": "score = 85\nif score >= 90:\n    print(\"优秀\")\nelse:\n    if score >= 60:\n        print(\"及格\")\n    else:\n        print(\"不及格\")", "description": "Determine grade level based on score: 90 and above is Excellent, 60 and above is Pass, otherwise Fail. Note the use of nested if: first check >=90, if false then check >=60.", "code_skeleton": "", "expected_output": "Pass"}, "i_stage": {"summary_points": ["if-else is used for conditional judgment", "Comparison operators return True or False", "Indentation distinguishes code blocks", "Nested if enables multi-level judgment"], "question_prompts": ["What will be output if the score is exactly 60?", "What happens if you change >= to >?"]}, "p_stage": {"subtasks": [{"id": 1, "title": "获取变量", "blocks": [{"color": "orange", "block_id": "variables_set", "block_type": "变量赋值", "explanation": "创建一个变量score，把85存进去。", "python_code": "score = 85"}]}, {"id": 2, "title": "条件判断", "blocks": [{"color": "blue", "block_id": "controls_if", "block_type": "if-else 判断", "explanation": "if 后面跟条件，条件成立执行 if 里的代码。注意冒号和缩进。", "python_code": "if score >= 60:\n    print(''及格'')\nelse:\n    print(''不及格'')"}, {"color": "orange", "block_id": "logic_compare", "block_type": "比较运算", "explanation": ">= 表示大于或等于。比较结果要么 True 要么 False。", "python_code": "score >= 60"}]}, {"id": 3, "title": "输出结果", "blocks": [{"color": "green", "block_id": "text_print", "block_type": "print 输出", "explanation": "print() 把内容显示到屏幕上。", "python_code": "print(''及格'')"}]}]}, "inferred_blocks": null}'
WHERE id = 1;

-- CN task 8 → EN task 2
UPDATE tasks
SET
  title = 'Task 2: for Loop Repetition',
  description = 'Learn for loops, let the computer automatically repeat operations',
  content_json = '{"a_stage": {"python_code": "for i in range(5):\n    print(\"-\")"}, "c_stage": {"title": "Countdown", "blocks_xml": "<xml xmlns=\"http://www.w3.org/1999/xhtml\">\n  <block type=\"variables_set\">\n    <field name=\"VAR\">n</field>\n    <value name=\"VALUE\">\n      <block type=\"math_number\">\n        <field name=\"NUM\">5</field>\n      </block>\n    </value>\n    <next>\n      <block type=\"controls_repeat_ext\">\n        <value name=\"TIMES\">\n          <block type=\"math_number\">\n            <field name=\"NUM\">5</field>\n          </block>\n        </value>\n        <statement name=\"DO\">\n          <block type=\"text_print\">\n            <value name=\"TEXT\">\n              <block type=\"variables_get\">\n                <field name=\"VAR\">n</field>\n              </block>\n            </value>\n            <next>\n              <block type=\"variables_set\">\n                <field name=\"VAR\">n</field>\n                <value name=\"VALUE\">\n                  <block type=\"math_arithmetic\">\n                    <field name=\"OP\">MINUS</field>\n                    <value name=\"A\">\n                      <block type=\"variables_get\">\n                        <field name=\"VAR\">n</field>\n                      </block>\n                    </value>\n                    <value name=\"B\">\n                      <block type=\"math_number\">\n                        <field name=\"NUM\">1</field>\n                      </block>\n                    </value>\n                  </block>\n                </value>\n              </block>\n            </next>\n          </block>\n        </statement>\n      </block>\n    </next>\n  </block>\n</xml>", "answer_code": "n = 5\nfor _ in range(5):\n    print(n)\n    n = n - 1", "description": "Count down from 5 to 1. Use a variable n=5, loop 5 times, output n each time then decrease n by 1.", "code_skeleton": "", "expected_output": "5\n4\n3\n2\n1"}, "i_stage": {"summary_points": ["for loop repeatedly executes code", "range(n) generates a sequence from 0 to n-1", "Indentation determines which code belongs to the loop body", "The variable i in the loop takes a different value each time"], "question_prompts": ["range(5) loops 5 times, but i goes from 0 to 4. Why?", "To draw a triangle with 7 lines, what should be changed?"]}, "p_stage": {"subtasks": [{"id": 1, "title": "for 循环结构", "blocks": [{"color": "blue", "block_id": "controls_repeat_ext", "block_type": "重复N次", "explanation": "range(5) 表示重复5次。执行的代码要有缩进。", "python_code": "for i in range(5):\n    print(''-'')"}, {"color": "orange", "block_id": "math_number", "block_type": "数字", "explanation": "range(5) 里的5表示循环次数，改成3就循环3次。", "python_code": "5"}]}, {"id": 2, "title": "print 在循环里", "blocks": [{"color": "green", "block_id": "text_print", "block_type": "print 输出", "explanation": "这个 print 在循环内部，所以会被执行5次，屏幕上打印5条短线。", "python_code": "print(''-'')"}]}]}, "inferred_blocks": null}'
WHERE id = 2;

-- CN task 9 → EN task 3
UPDATE tasks
SET
  title = 'Task 3: Input and Conditionals',
  description = 'Learn to use input() to get user input, and combine with conditionals to respond differently',
  content_json = '{"a_stage": {"python_code": "name = input(\"请输入你的名字：\")\nprint(\"你好，\" + name)"}, "c_stage": {"title": "Input Name and Check Length", "blocks_xml": "<xml xmlns=\"https://developers.google.com/blockly/xml\">\n  <block type=\"variables_set\">\n    <field name=\"VAR\">name</field>\n    <value name=\"VALUE\">\n      <block type=\"sensing_ask\">\n        <value name=\"PROMPT\">\n          <block type=\"text\">\n            <field name=\"TEXT\">Please enter your name:</field>\n          </block>\n        </value>\n      </block>\n    </value>\n    <next>\n      <block type=\"controls_if\">\n        <value name=\"IF0\">\n          <block type=\"logic_compare\">\n            <field name=\"OP\">GT</field>\n            <value name=\"A\">\n              <block type=\"text_length\">\n                <value name=\"VALUE\">\n                  <block type=\"variables_get\">\n                    <field name=\"VAR\">name</field>\n                  </block>\n                </value>\n              </block>\n            </value>\n            <value name=\"B\">\n              <block type=\"math_number\">\n                <field name=\"NUM\">3</field>\n              </block>\n            </value>\n          </block>\n        </value>\n        <statement name=\"DO0\">\n          <block type=\"text_print\">\n            <value name=\"TEXT\">\n              <block type=\"text\">\n                <field name=\"TEXT\">Name is long</field>\n              </block>\n            </value>\n          </block>\n        </statement>\n        <statement name=\"ELSE\">\n          <block type=\"text_print\">\n            <value name=\"TEXT\">\n              <block type=\"text\">\n                <field name=\"TEXT\">Name is short</field>\n              </block>\n            </value>\n          </block>\n        </statement>\n      </block>\n    </next>\n  </block>\n</xml>", "answer_code": "name = input(\"请输入你的名字：\")\nif len(name) > 3:\n    print(\"名字很长\")\nelse:\n    print(\"名字很短\")", "description": "After entering a name, check its length: if more than 3 characters output [Name is long], otherwise output [Name is short]. Hint: use len() to get string length.", "code_skeleton": "", "expected_output": "Name is long"}, "i_stage": {"summary_points": ["input() gets user input, returns a string", "len() calculates string length", "After getting input, store it in a variable for reuse", "input + if enables interactive judgment"], "question_prompts": ["If the user doesn''t enter anything and just presses Enter, what does len() return?", "Can you use input() to get a number first, then use if to compare its size?"]}, "p_stage": {"subtasks": [{"id": 1, "title": "获取输入", "blocks": [{"color": "green", "block_id": "sensing_ask", "block_type": "询问并等待(input)", "explanation": "input() 让程序停下来等用户输入。括号里是提示语。", "python_code": "name = input(''请输入你的名字：'')"}]}, {"id": 2, "title": "存储到变量", "blocks": [{"color": "orange", "block_id": "variables_set", "block_type": "变量赋值", "explanation": "把 input() 拿到的东西存到变量 name 里。", "python_code": "name = ..."}]}, {"id": 3, "title": "长度判断", "blocks": [{"color": "purple", "block_id": "text_length", "block_type": "字符串长度", "explanation": "len() 返回字符串的长度（有几个字）。输入''小明''，len() 返回2。", "python_code": "len(name)"}]}, {"id": 4, "title": "条件输出", "blocks": [{"color": "blue", "block_id": "controls_if", "block_type": "if-else 判断", "explanation": "先用 len() 得到名字长度，再用 if 判断是否大于3。", "python_code": "if len(name) > 3:\n    print(''名字很长'')\nelse:\n    print(''名字很短'')"}]}]}, "inferred_blocks": null}'
WHERE id = 3;

-- CN task 10 → EN task 4
UPDATE tasks
SET
  title = 'Task 4: Conditionals Inside Loops',
  description = 'Combine for loops and if conditionals, process data one by one and classify output',
  content_json = '{"a_stage": {"python_code": "for i in range(10):\n    if i % 2 == 0:\n        print(\"偶\")\n    else:\n        print(\"奇\")"}, "c_stage": {"title": "Count Even Numbers", "blocks_xml": "<xml xmlns=\"https://developers.google.com/blockly/xml\">\n  <block type=\"variables_set\">\n    <field name=\"VAR\">count</field>\n    <value name=\"VALUE\">\n      <block type=\"math_number\">\n        <field name=\"NUM\">0</field>\n      </block>\n    </value>\n    <next>\n      <block type=\"controls_repeat_ext\">\n        <value name=\"TIMES\">\n          <block type=\"math_number\">\n            <field name=\"NUM\">10</field>\n          </block>\n        </value>\n        <statement name=\"DO\">\n          <block type=\"controls_if\">\n            <value name=\"IF0\">\n              <block type=\"math_arithmetic\">\n                <field name=\"OP\">MODULO</field>\n                <value name=\"A\">\n                  <block type=\"variables_get\">\n                    <field name=\"VAR\">i</field>\n                  </block>\n                </value>\n                <value name=\"B\">\n                  <block type=\"math_number\">\n                    <field name=\"NUM\">2</field>\n                  </block>\n                </value>\n              </block>\n            </value>\n            <statement name=\"DO0\">\n              <block type=\"variables_set\">\n                <field name=\"VAR\">count</field>\n                <value name=\"VALUE\">\n                  <block type=\"math_arithmetic\">\n                    <field name=\"OP\">ADD</field>\n                    <value name=\"A\">\n                      <block type=\"variables_get\">\n                        <field name=\"VAR\">count</field>\n                      </block>\n                    </value>\n                    <value name=\"B\">\n                      <block type=\"math_number\">\n                        <field name=\"NUM\">1</field>\n                      </block>\n                    </value>\n                  </block>\n                </value>\n              </block>\n            </statement>\n          </block>\n        </statement>\n        <next>\n          <block type=\"text_print\">\n            <value name=\"TEXT\">\n              <block type=\"variables_get\">\n                <field name=\"VAR\">count</field>\n              </block>\n            </value>\n          </block>\n        </next>\n      </block>\n    </next>\n  </block>\n</xml>", "answer_code": "count = 0\nfor i in range(10):\n    if i % 2 == 0:\n        count = count + 1\nprint(count)", "description": "Loop 10 times, count how many even numbers there are. Hint: start with a variable count=0, increment count by 1 each time you encounter an even number.", "code_skeleton": "", "expected_output": "5"}, "i_stage": {"summary_points": ["for loop can iterate over a range of numbers", "% modulo operation can determine odd/even", "if can be placed inside a loop for per-iteration judgment", "Using a variable to count is a common programming technique"], "question_prompts": ["If counting odd numbers instead of even numbers, what needs to be changed in the code?", "Is count = count + 1 the same as count += 1?"]}, "p_stage": {"subtasks": [{"id": 1, "title": "循环回顾", "blocks": [{"color": "blue", "block_id": "controls_repeat_ext", "block_type": "重复N次", "explanation": "回顾：for 循环让 print(i) 执行 10 次，i 从 0 到 9。", "python_code": "for i in range(10):\n    print(i)"}]}, {"id": 2, "title": "取余运算", "blocks": [{"color": "orange", "block_id": "math_arithmetic", "block_type": "加减乘除取余", "explanation": "% 是取余数运算。i % 2 得到 i 除以 2 的余数。余数为 0 说明 i 是偶数。", "python_code": "i % 2"}]}, {"id": 3, "title": "循环里判断", "blocks": [{"color": "blue", "block_id": "controls_if", "block_type": "if-else 判断", "explanation": "把 if 放进循环里——每轮循环都执行一次判断。", "python_code": "if i % 2 == 0:\n    print(''偶'')\nelse:\n    print(''奇'')"}]}]}, "inferred_blocks": null}'
WHERE id = 4;
